SELECT a.id,a.user_id,a.certificate_id,a.holder_name_encrypted,a.number_type,a.number_encrypted,a.number_hash,a.obtained_on,a.attachment_id,a.auxiliary_id,a.note,a.revision,a.auto_result,a.auto_details,a.official_result,a.status,a.created_at,a.updated_at,c.name certificate_name,u.username FROM certificate_application a JOIN certificate c ON c.id=a.certificate_id JOIN app_user u ON u.id=a.user_id
a.user_id=#{userId}
ORDER BY a.created_at DESC

SELECT a.id,a.user_id,a.certificate_id,a.holder_name_encrypted,a.number_type,a.number_encrypted,a.number_hash,a.obtained_on,a.attachment_id,a.auxiliary_id,a.note,a.revision,a.auto_result,a.auto_details,a.official_result,a.status,a.created_at,a.updated_at,c.name certificate_name,u.username FROM certificate_application a JOIN certificate c
    ON c.id=a.certificate_id JOIN app_user u ON u.id=a.user_id

      a.user_id=#{userId}

ORDER BY a.ida.created_at ASCDESC, a.id ASC LIMIT #{query.size} OFFSET #{query.offset}

SELECT count(*) FROM (SELECT a.id,a.user_id,a.certificate_id,a.holder_name_encrypted,a.number_type,a.number_encrypted,a.number_hash,a.obtained_on,a.attachment_id,a.auxiliary_id,a.note,a.revision,a.auto_result,a.auto_details,a.official_result,a.status,a.created_at,a.updated_at,c.name certificate_name,u.username FROM certificate_application a JOIN certificate c
    ON c.id=a.certificate_id JOIN app_user u ON u.id=a.user_id

      a.user_id=#{userId}
    ) page_count
